export function parseMove(str, duration) {
  const face = str[0].toUpperCase();
  const prime = str.includes("'") || str[1] === 'i';
  const def = FACE_TURNS[face];
  if (!def) return null;
  const axis = new THREE.Vector3(...def.axis).normalize();
