```js
enqueue(move) {
  if (!move) return;
  this.queue.push(move);
  if (this.queue.length > 120) this.queue.splice(0, this.queue.length - 120);
}

get busy() { return this.active !== null; }

update(dt) {
  if (!this.active) {
    const next = this.queue.shift();
    if (!next) return;
    this._begin(next);
  }
  const move = this.active;
  move.elapsed = (move.elapsed ?? 0) + dt;
  const duration = move.duration ?? 0.16;
  const t = Math.min(1, duration > 0 ? move.elapsed / duration : 1);
  this.pivot.quaternion.setFromAxisAngle(move.axis, move.angle * easeInOutCubic(t));
  if (t >= 1) this._finish();
}
```

_begin:

```js
_begin(move) {
  this.active = move;
  this.pivot.quaternion.identity();
  this.updateMatrixWorld(true);
  for (const cubie of this.cubies) {
    const coord = Math.round(cubie.position[move.axisName]);
    if (move.layer === 'all' || coord === move.layer) {
      this.pivot.attach(cubie);
    }
  }
}
```

