_finish:

```js
_finish() {
  const move = this.active;
  this.pivot.quaternion.setFromAxisAngle(move.axis, move.angle);
  this.pivot.updateMatrixWorld(true);
  for (const cubie of this.cubies) {
    if (cubie.parent !== this.pivot) continue;
    this.attach(cubie);
    snapCubie(cubie);
  }
  this.pivot.quaternion.identity();
  this.active = null;
  this.dispatchEvent?.({ type: 'move', move }); // Object3D has dispatchEvent
}
```

