/**
 * cube.js — the Rubik's cube model.
 *
 * The cube is made of 26 rounded "cubies" (the core is invisible).  Each
 * cubie carries colored stickers as children.  Turns are animatable:
 * a temporary pivot group is rotated, cubies of the selected layer are
 * attached to it, and when the turn finishes they are re-attached to the
 * cube and their transforms are snapped to the exact 90° lattice so the
 * cube never drifts.
 */

import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/examples/jsm/geometries/RoundedBoxGeometry.js';

export const CUBIE_SIZE = 0.94; // world units, cubies are spaced 1.0 apart
const STICKER_SIZE = 0.72;
const STICKER_RADIUS = 0.13;
const STICKER_LIFT = 0.012;
const DEFAULT_TURN_TIME = 0.16; // seconds

/** Sticker colors, one per face (western color scheme). */
export const FACE_COLORS = {
  R: 0xd63031, // +x  red
  L: 0xff7f1f, // -x  orange
  U: 0xf7f7f7, // +y  white
  D: 0xffd21e, // -y  yellow
  F: 0x21b25c, // +z  green
  B: 0x1e6fd9, // -z  blue
};

const FACE_DEFS = [
  { key: 'R', normal: new THREE.Vector3(1, 0, 0) },
  { key: 'L', normal: new THREE.Vector3(-1, 0, 0) },
  { key: 'U', normal: new THREE.Vector3(0, 1, 0) },
  { key: 'D', normal: new THREE.Vector3(0, -1, 0) },
  { key: 'F', normal: new THREE.Vector3(0, 0, 1) },
  { key: 'B', normal: new THREE.Vector3(0, 0, -1) },
];

/**
 * Turn definitions.  `axis` is the rotation axis (a unit vector along a
 * signed basis direction) and a positive angle follows it.  A clockwise
 * face turn (seen from outside the face) rotates about the face's inward
 * normal, hence the negated axes.
 */
const TURN_DEFS = {
  U: { axis: [0, -1, 0], name: 'y', layer: 1 },
  D: { axis: [0, 1, 0], name: 'y', layer: -1 },
  R: { axis: [-1, 0, 0], name: 'x', layer: 1 },
  L: { axis: [1, 0, 0], name: 'x', layer: -1 },
  F: { axis: [0, 0, -1], name: 'z', layer: 1 },
  B: { axis: [0, 0, 1], name: 'z', layer: -1 },
  M: { axis: [1, 0, 0], name: 'x', layer: 0 }, // middle slice, follows L
  E: { axis: [0, 1, 0], name: 'y', layer: 0 }, // equator slice, follows D
  S: { axis: [0, 0, -1], name: 'z', layer: 0 }, // standing slice, follows F
  X: { axis: [-1, 0, 0], name: 'x', layer: 'all' }, // whole cube, follows R
  Y: { axis: [0, -1, 0], name: 'y', layer: 'all' }, // whole cube, follows U
  Z: { axis: [0, 0, -1], name: 'z', layer: 'all' }, // whole cube, follows F
};

const AXIS_NAMES = ['x', 'y', 'z'];
const Z_AXIS = new THREE.Vector3(0, 0, 1);

/** Rounded-square ShapeGeometry used for every sticker. */
function roundedRectGeometry(size, radius) {
  const h = size / 2;
  const r = Math.min(radius, h);
  const shape = new THREE.Shape();
  shape.moveTo(-h + r, -h);
  shape.lineTo(h - r, -h);
  shape.quadraticCurveTo(h, -h, h, -h + r);
  shape.lineTo(h, h - r);
  shape.quadraticCurveTo(h, h, h - r, h);
  shape.lineTo(-h + r, h);
  shape.quadraticCurveTo(-h, h, -h, h - r);
  shape.lineTo(-h, -h + r);
  shape.quadraticCurveTo(-h, -h, -h + r, -h);
  return new THREE.ShapeGeometry(shape, 10);
}

function easeInOutCubic(t) {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
}

/** Snap a cubie to the exact position/rotation lattice after a turn. */
function snapCubie(cubie) {
  const p = cubie.position;
  p.set(Math.round(p.x), Math.round(p.y), Math.round(p.z));

  const m = new THREE.Matrix4().makeRotationFromQuaternion(cubie.quaternion);
  const e = m.elements;
  for (let i = 0; i < 16; i++) e[i] = Math.round(e[i]);
  cubie.quaternion.setFromRotationMatrix(m);
}

/**
 * Parse standard cube notation: "R", "R'", "M", "x", "Y'" ...
 * Returns a move description understood by RubiksCube#enqueue.
 */
export function parseMove(notation, duration = DEFAULT_TURN_TIME) {
  if (typeof notation !== 'string' || notation.length === 0) return null;
  const face = notation[0].toUpperCase();
  const def = TURN_DEFS[face];
  if (!def) return null;
  const suffix = notation.slice(1);
  const prime = suffix === "'" || suffix === '’' || suffix.toLowerCase() === 'i';

  const axis = new THREE.Vector3(...def.axis).normalize();
  return {
    notation: face + (prime ? "'" : ''),
    axis,
    axisName: def.name,
    layer: def.layer,
    angle: ((prime ? -1 : 1) * Math.PI) / 2,
    duration,
    elapsed: 0,
  };
}

/** A random face-turn sequence (no two turns on the same face in a row). */
export function randomScramble(count = 22) {
  const faces = ['U', 'D', 'L', 'R', 'F', 'B'];
  const moves = [];
  let last = null;
  while (moves.length < count) {
    const face = faces[(Math.random() * faces.length) | 0];
    if (face === last) continue;
    last = face;
    moves.push(face + (Math.random() < 0.5 ? "'" : ''));
  }
  return moves;
}

export class RubiksCube extends THREE.Group {
  constructor() {
    super();
    this.name = 'RubiksCube';

    /** @type {THREE.Group[]} */
    this.cubies = [];
    /** @type {object[]} moves waiting to be animated */
    this.queue = [];
    /** @type {object|null} move currently being animated */
    this.active = null;

    // Turning is done by rotating a pivot and moving the affected cubies
    // onto it for the duration of the animation.
    this.pivot = new THREE.Group();
    this.pivot.name = 'turnPivot';
    this.add(this.pivot);

    this._bodyGeometry = new RoundedBoxGeometry(CUBIE_SIZE, CUBIE_SIZE, CUBIE_SIZE, 4, 0.075);
    this._bodyMaterial = new THREE.MeshStandardMaterial({
      color: 0x14161a,
      roughness: 0.42,
      metalness: 0.12,
      envMapIntensity: 0.7,
    });
    this._stickerGeometry = roundedRectGeometry(STICKER_SIZE, STICKER_RADIUS);
    this._stickerMaterials = new Map();

    this._build();
  }

  _build() {
    for (let x = -1; x <= 1; x++) {
      for (let y = -1; y <= 1; y++) {
        for (let z = -1; z <= 1; z++) {
          if (x === 0 && y === 0 && z === 0) continue; // invisible core
          this.add(this._buildCubie(x, y, z));
        }
      }
    }
  }

  _buildCubie(x, y, z) {
    const cubie = new THREE.Group();
    cubie.position.set(x, y, z);
    cubie.userData.home = cubie.position.clone();
    cubie.userData.stickers = [];

    const body = new THREE.Mesh(this._bodyGeometry, this._bodyMaterial);
    body.castShadow = true;
    body.receiveShadow = true;
    body.userData.cubie = cubie;
    cubie.add(body);

    for (const face of FACE_DEFS) {
      const { normal } = face;
      // Only cubies on the outside of that face get a sticker.
      const onFace =
        (normal.x !== 0 && x === normal.x) ||
        (normal.y !== 0 && y === normal.y) ||
        (normal.z !== 0 && z === normal.z);
      if (!onFace) continue;

      const sticker = new THREE.Mesh(this._stickerGeometry, this._stickerMaterial(face.key));
      sticker.quaternion.setFromUnitVectors(Z_AXIS, normal);
      sticker.position.copy(normal).multiplyScalar(CUBIE_SIZE / 2 + STICKER_LIFT);
      sticker.userData.cubie = cubie;
      sticker.userData.normal = normal.clone();
      sticker.userData.color = face.key;
      cubie.add(sticker);
      cubie.userData.stickers.push(sticker);
    }

    this.cubies.push(cubie);
    return cubie;
  }

  _stickerMaterial(faceKey) {
    if (!this._stickerMaterials.has(faceKey)) {
      this._stickerMaterials.set(
        faceKey,
        new THREE.MeshPhysicalMaterial({
          color: FACE_COLORS[faceKey],
          roughness: 0.34,
          metalness: 0.0,
          clearcoat: 1.0,
          clearcoatRoughness: 0.24,
          envMapIntensity: 0.9,
        }),
      );
    }
    return this._stickerMaterials.get(faceKey);
  }

  /** True while a turn animation is running. */
  get busy() {
    return this.active !== null;
  }

  /** Queue a move; `move` comes from parseMove(). */
  enqueue(move) {
    if (!move) return;
    this.queue.push(move);
    // Never let an over-eager key repeat build an unbounded backlog.
    if (this.queue.length > 120) this.queue.splice(0, this.queue.length - 120);
  }

  /** Advance the current animation (dt in seconds). */
  update(dt) {
    if (!this.active) {
      const next = this.queue.shift();
      if (!next) return;
      this._begin(next);
    }

    const move = this.active;
    const duration = move.duration ?? DEFAULT_TURN_TIME;
    move.elapsed += dt;
    const t = duration > 0 ? Math.min(1, move.elapsed / duration) : 1;
    this.pivot.quaternion.setFromAxisAngle(move.axis, move.angle * easeInOutCubic(t));

    if (t >= 1) this._finish();
  }

  _begin(move) {
    this.active = move;
    this.pivot.quaternion.identity();
    this.updateMatrixWorld(true);

    for (const cubie of this.cubies) {
      const coord = Math.round(cubie.position[move.axisName]);
      if (move.layer === 'all' || coord === move.layer) {
        this.pivot.attach(cubie);
      }
    }
  }

  _finish() {
    const move = this.active;
    this.pivot.quaternion.setFromAxisAngle(move.axis, move.angle);
    this.pivot.updateMatrixWorld(true);

    for (const cubie of this.cubies) {
      if (cubie.parent !== this.pivot) continue;
      this.attach(cubie);
      snapCubie(cubie);
    }

    this.pivot.quaternion.identity();
    this.active = null;
    this.dispatchEvent({ type: 'movecomplete', move });
  }

  /** Instantly restore the solved state. */
  reset() {
    this.queue.length = 0;
    this.active = null;
    this.pivot.quaternion.identity();
    for (const cubie of this.cubies) {
      if (cubie.parent !== this) this.add(cubie);
      cubie.position.copy(cubie.userData.home);
      cubie.quaternion.identity();
    }
  }

  /**
   * True when every face shows a single color (any whole-cube orientation
   * counts as solved).
   */
  isSolved() {
    const dir = new THREE.Vector3();
    for (const face of FACE_DEFS) {
      const { normal } = face;
      let color = null;
      for (const cubie of this.cubies) {
        if (Math.round(cubie.position.dot(normal)) !== 1) continue;
        for (const sticker of cubie.userData.stickers) {
          dir.copy(sticker.userData.normal).applyQuaternion(cubie.quaternion);
          if (dir.dot(normal) > 0.9) {
            const key = sticker.userData.color;
            if (color === null) color = key;
            else if (key !== color) return false;
          }
        }
      }
    }
    return true;
  }
}

/**
 * main.js — interactive Rubik's cube.
 *
 * Controls
 *   • Drag a sticker/face → turn that layer
 *   • Drag the background → orbit the camera
 *   • Wheel / pinch      → zoom
 *   • U D L R F B (hold Shift for inverse), M E S slices, X Y Z whole cube
 */

import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/examples/jsm/environments/RoomEnvironment.js';
import { RubiksCube, parseMove, randomScramble } from './cube.js';

// ---------------------------------------------------------------------------
// Renderer / scene / camera
// ---------------------------------------------------------------------------

const stage = document.getElementById('stage');

const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.NeutralToneMapping;
renderer.toneMappingExposure = 1.0;
renderer.domElement.setAttribute('aria-label', "Interactive Rubik's cube");
stage.appendChild(renderer.domElement);

const scene = new THREE.Scene();

const camera = new THREE.PerspectiveCamera(38, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(4.7, 4.1, 5.7);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 0, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.08;
controls.enablePan = false;
controls.minDistance = 4.6;
controls.maxDistance = 14;
controls.minPolarAngle = 0.12;
controls.maxPolarAngle = Math.PI - 0.12;
controls.rotateSpeed = 0.85;
controls.zoomSpeed = 0.9;
controls.autoRotate = true;
controls.autoRotateSpeed = 0.7;

// ---------------------------------------------------------------------------
// Lighting (all procedural — no external assets)
// ---------------------------------------------------------------------------

const pmrem = new THREE.PMREMGenerator(renderer);
const environment = pmrem.fromScene(new RoomEnvironment(), 0.04);
scene.environment = environment.texture;
scene.environmentIntensity = 0.65;
pmrem.dispose();

const hemi = new THREE.HemisphereLight(0xdfe9ff, 0x2c3242, 0.7);
scene.add(hemi);

const keyLight = new THREE.DirectionalLight(0xffffff, 2.1);
keyLight.position.set(6, 10, 7);
keyLight.castShadow = true;
keyLight.shadow.mapSize.set(2048, 2048);
keyLight.shadow.camera.left = -6;
keyLight.shadow.camera.right = 6;
keyLight.shadow.camera.top = 6;
keyLight.shadow.camera.bottom = -6;
keyLight.shadow.camera.near = 1;
keyLight.shadow.camera.far = 30;
keyLight.shadow.bias = -0.0004;
keyLight.shadow.normalBias = 0.02;
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x9db8ff, 0.55);
fillLight.position.set(-7, -4, -6);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xffe3c2, 0.4);
rimLight.position.set(-4, 6, -8);
scene.add(rimLight);

// Soft shadow catcher so the cube appears to float over the background.
const shadowPlane = new THREE.Mesh(
  new THREE.PlaneGeometry(40, 40),
  new THREE.ShadowMaterial({ color: 0x000000, opacity: 0.32, transparent: true }),
);
shadowPlane.rotation.x = -Math.PI / 2;
shadowPlane.position.y = -1.78;
shadowPlane.receiveShadow = true;
scene.add(shadowPlane);

// ---------------------------------------------------------------------------
// The cube
// ---------------------------------------------------------------------------

const cube = new RubiksCube();
scene.add(cube);

// Small squash-and-stretch flourish while a turn animates.
const CUBE_SCALE = 1.0;
cube.scale.setScalar(CUBE_SCALE);

// ---------------------------------------------------------------------------
// Pointer interaction: drag a face to turn its layer
// ---------------------------------------------------------------------------

const raycaster = new THREE.Raycaster();
const pointerNdc = new THREE.Vector2();
const clock = new THREE.Clock();

/** @type {null | {pointerId:number, startX:number, startY:number, cubie:THREE.Group, normal:THREE.Vector3, tangents:THREE.Vector3[], screenDirs:{x:number,y:number}[], triggered:boolean}} */
let drag = null;

function castCubie(clientX, clientY) {
  const rect = renderer.domElement.getBoundingClientRect();
  pointerNdc.x = ((clientX - rect.left) / rect.width) * 2 - 1;
  pointerNdc.y = -((clientY - rect.top) / rect.height) * 2 + 1;
  raycaster.setFromCamera(pointerNdc, camera);

  const hits = raycaster.intersectObjects(cube.cubies, true);
  if (hits.length === 0) return null;

  let object = hits[0].object;
  while (object && !object.userData.cubie) object = object.parent;
  if (!object) return null;

  return { cubie: object.userData.cubie, point: hits[0].point.clone() };
}

/** Screen-space direction (px) of a world-space direction at a world point. */
function screenDirection(worldPoint, worldDir) {
  const p1 = worldPoint.clone().project(camera);
  const p2 = worldPoint
    .clone()
    .addScaledVector(worldDir, 0.25)
    .project(camera);
  const dx = ((p2.x - p1.x) * window.innerWidth) / 2;
  const dy = (-(p2.y - p1.y) * window.innerHeight) / 2;
  const len = Math.hypot(dx, dy) || 1e-6;
  return { x: dx / len, y: dy / len };
}

const _worldQuat = new THREE.Quaternion();

function onPointerDown(event) {
  if (event.pointerType === 'mouse' && event.button !== 0) return;
  if (drag) return;

  // Let orbit controls handle the gesture while a turn is animating.
  if (cube.busy) return;

  const hit = castCubie(event.clientX, event.clientY);
  if (!hit) return;

  const { cubie } = hit;

  // Which face did we grab? Work in cube-local space and snap the hit
  // offset from the cubie center to the dominant axis.
  const localPoint = cube.worldToLocal(hit.point.clone());
  const offset = localPoint.sub(cubie.position);
  let axis = 'x';
  if (Math.abs(offset.y) > Math.abs(offset[axis])) axis = 'y';
  if (Math.abs(offset.z) > Math.abs(offset[axis])) axis = 'z';

  const normal = new THREE.Vector3();
  normal[axis] = Math.sign(offset[axis]) || 1;

  // The two in-plane axes are the candidate drag directions.
  const tangents = ['x', 'y', 'z']
    .filter((name) => name !== axis)
    .map((name) => new THREE.Vector3(name === 'x' ? 1 : 0, name === 'y' ? 1 : 0, name === 'z' ? 1 : 0));

  cube.getWorldQuaternion(_worldQuat);
  const screenDirs = tangents.map((t) => screenDirection(hit.point, t.clone().applyQuaternion(_worldQuat)));

  drag = {
    pointerId: event.pointerId,
    startX: event.clientX,
    startY: event.clientY,
    cubie,
    normal,
    tangents,
    screenDirs,
    triggered: false,
  };

  controls.enabled = false; // this gesture turns layers, it doesn't orbit
  controls.autoRotate = false;
  renderer.domElement.setPointerCapture(event.pointerId);
}

function onPointerMove(event) {
  if (!drag || event.pointerId !== drag.pointerId) return;

  if (drag.triggered) {
    // Let a continuous drag chain further turns once the last one finished.
    if (!cube.busy) {
      drag.triggered = false;
      drag.startX = event.clientX;
      drag.startY = event.clientY;
    } else {
      return;
    }
  }

  const dx = event.clientX - drag.startX;
  const dy = event.clientY - drag.startY;
  if (Math.hypot(dx, dy) < 12) return;

  // Pick the in-plane axis the drag points along most strongly.
  let best = 0;
  let bestScore = -Infinity;
  let bestSign = 1;
  for (let i = 0; i < drag.tangents.length; i++) {
    const dir = drag.screenDirs[i];
    const dot = dx * dir.x + dy * dir.y;
    if (Math.abs(dot) > bestScore) {
      bestScore = Math.abs(dot);
      best = i;
      bestSign = Math.sign(dot) || 1;
    }
  }

  // Rotating about (faceNormal × dragDirection) moves the face along the
  // drag when the angle is positive.
  const dragDir = drag.tangents[best].clone().multiplyScalar(bestSign);
  const axisVec = new THREE.Vector3().crossVectors(drag.normal, dragDir);
  const axisName = ['x', 'y', 'z'].reduce((a, b) => (Math.abs(axisVec[a]) >= Math.abs(axisVec[b]) ? a : b));
  const layer = Math.round(drag.cubie.position[axisName]);

  cube.enqueue({
    notation: 'drag',
    axis: axisVec.normalize(),
    axisName,
    layer,
    angle: Math.PI / 2,
    duration: 0.15,
    elapsed: 0,
  });
  drag.triggered = true;
  hud.userMove();
}

function endPointer(event) {
  if (!drag || (event && event.pointerId !== drag.pointerId)) return;
  drag = null;
  controls.enabled = true;
}

renderer.domElement.addEventListener('pointerdown', onPointerDown);
renderer.domElement.addEventListener('pointermove', onPointerMove);
renderer.domElement.addEventListener('pointerup', endPointer);
renderer.domElement.addEventListener('pointercancel', endPointer);

// ---------------------------------------------------------------------------
// Keyboard
// ---------------------------------------------------------------------------

window.addEventListener('keydown', (event) => {
  if (event.metaKey || event.ctrlKey || event.altKey) return;
  const notation = event.key.length === 1 ? event.key + (event.shiftKey ? "'" : '') : '';
  const move = parseMove(notation, 0.16);
  if (!move) return;
  event.preventDefault();
  controls.autoRotate = false;
  hud.userMove();
  cube.enqueue(move);
});

// ---------------------------------------------------------------------------
// HUD: timer, move counter, toast
// ---------------------------------------------------------------------------

const timerEl = document.getElementById('timer');
const movesEl = document.getElementById('moves');
const toastEl = document.getElementById('toast');

const hud = {
  scrambled: false,
  scrambling: false,
  timerRunning: false,
  timerStart: 0,
  timerElapsed: 0,
  moves: 0,
  solvedShown: false,

  formatTime(seconds) {
    return seconds.toFixed(2);
  },

  refresh() {
    timerEl.textContent = this.formatTime(this.timerElapsed);
    movesEl.textContent = String(this.moves);
  },

  resetStats() {
    this.timerRunning = false;
    this.timerStart = 0;
    this.timerElapsed = 0;
    this.moves = 0;
    this.solvedShown = false;
    this.refresh();
    toastEl.classList.remove('show');
  },

  userMove() {
    this.moves += 1;
    this.refresh();
    if (this.scrambled && !this.scrambling && !this.timerRunning) {
      this.timerRunning = true;
      this.timerStart = performance.now();
    }
    if (this.solvedShown) {
      this.solvedShown = false;
      toastEl.classList.remove('show');
    }
  },

  tick(now) {
    if (!this.timerRunning) return;
    this.timerElapsed = (now - this.timerStart) / 1000;
    timerEl.textContent = this.formatTime(this.timerElapsed);
  },

  stopTimer() {
    if (!this.timerRunning) return;
    this.timerElapsed = (performance.now() - this.timerStart) / 1000;
    this.timerRunning = false;
    this.refresh();
  },
};

document.getElementById('scramble').addEventListener('click', () => {
  hud.resetStats();
  hud.scrambling = true;
  hud.scrambled = true;
  for (const notation of randomScramble(20)) {
    cube.enqueue(parseMove(notation, 0.085));
  }
});

document.getElementById('reset').addEventListener('click', () => {
  cube.reset();
  hud.scrambling = false;
  hud.scrambled = false;
  hud.resetStats();
});

cube.addEventListener('movecomplete', () => {
  if (hud.scrambling && !cube.busy && cube.queue.length === 0) {
    hud.scrambling = false;
  }
  if (hud.scrambled && hud.timerRunning && !hud.scrambling && cube.isSolved()) {
    hud.stopTimer();
    hud.solvedShown = true;
    toastEl.textContent = `Solved in ${hud.formatTime(hud.timerElapsed)}s · ${hud.moves} moves`;
    toastEl.classList.add('show');
  }
});

// ---------------------------------------------------------------------------
// Resize + render loop
// ---------------------------------------------------------------------------

function onResize() {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(window.innerWidth, window.innerHeight);
}
window.addEventListener('resize', onResize);

function frame(now) {
  const dt = Math.min(clock.getDelta(), 0.05);
  controls.update();
  cube.update(dt);
  hud.tick(now);
  renderer.render(scene, camera);
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

// Handy for debugging / automated checks.
window.__rubik = {
  cube,
  camera,
  scene,
  renderer,
  controls,
  apply: (notation) => {
    const move = parseMove(notation, 0.16);
    if (move) cube.enqueue(move);
    return move;
  },
  scramble: () => document.getElementById('scramble').click(),
  reset: () => document.getElementById('reset').click(),
};

