import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { extname, join, normalize } from 'node:path';
import { chromium } from 'playwright-core';

const ROOT = process.argv[2] || '.';
const PORT = 8231;
const MIME = {
  '.html': 'text/html',
  '.js': 'text/javascript',
  '.mjs': 'text/javascript',
  '.css': 'text/css',
  '.json': 'application/json',
};

const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://localhost');
    let path = decodeURIComponent(url.pathname);
    if (path === '/') path = '/index.html';
    const file = normalize(join(ROOT, path));
    const body = await readFile(file);
    res.writeHead(200, { 'Content-Type': MIME[extname(file)] || 'application/octet-stream' });
    res.end(body);
  } catch {
    res.writeHead(404);
    res.end('not found');
  }
});
await new Promise((r) => server.listen(PORT, r));

const exe = '~/Library/Caches/ms-playwright/chromium-1234/chrome-mac-arm64/Google Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing';
const browser = await chromium.launch({
  executablePath: exe,
  headless: true,
  args: ['--enable-unsafe-swiftshader', '--use-angle=swiftshader', '--disable-gpu-sandbox'],
});
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });

const errors = [];
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => {
  if (m.type() === 'error') errors.push('console: ' + m.text());
});

await page.goto(`http://localhost:${PORT}/index.html`, { waitUntil: 'load' });
await page.waitForFunction(() => !!window.__rubik, null, { timeout: 15000 });
await page.waitForTimeout(800);

const drain = () =>
  page.waitForFunction(() => !window.__rubik.cube.busy && window.__rubik.cube.queue.length === 0, null, {
    timeout: 20000,
  });

const results = {};
results.cubies = await page.evaluate(() => window.__rubik.cube.cubies.length);
results.solvedAtStart = await page.evaluate(() => window.__rubik.cube.isSolved());
results.webgl = await page.evaluate(() => {
  const gl = window.__rubik.renderer.getContext();
  return !!gl && !gl.isContextLost();
});

// R then R' returns to solved
await page.evaluate(() => window.__rubik.apply('R'));
await drain();
results.afterR = await page.evaluate(() => window.__rubik.cube.isSolved());
await page.evaluate(() => window.__rubik.apply("R'"));
await drain();
results.afterRprime = await page.evaluate(() => window.__rubik.cube.isSolved());

// keyboard input: press "u", then shift+u
await page.keyboard.press('u');
await drain();
results.afterKeyU = await page.evaluate(() => window.__rubik.cube.isSolved());
const afterU = await page.evaluate(() => window.__rubik.cube.cubies.map((c) => c.position.toArray()));
await page.keyboard.press('Shift+u');
await drain();
results.afterKeyShiftU = await page.evaluate(() => window.__rubik.cube.isSolved());
const afterU2 = await page.evaluate(() => window.__rubik.cube.cubies.map((c) => c.position.toArray()));
results.keyboardChangedState = JSON.stringify(afterU) !== JSON.stringify(afterU2);

// scramble
await page.evaluate(() => window.__rubik.scramble());
await page.waitForTimeout(300);
results.scramblingQueue = await page.evaluate(() => window.__rubik.cube.queue.length);
await drain();
results.scrambledNotSolved = !(await page.evaluate(() => window.__rubik.cube.isSolved()));

// reset
await page.evaluate(() => window.__rubik.reset());
await drain();
results.solvedAfterReset = await page.evaluate(() => window.__rubik.cube.isSolved());

// drag a visible front-layer cubie horizontally should change state
const dragStart = await page.evaluate(() => {
  const { cube, camera } = window.__rubik;
  const THREE = window.__THREE_TEST__;
  const cubie = cube.cubies.find((c) => c.position.x === 1 && c.position.y === 0 && c.position.z === 1);
  const p = cubie.position.clone().project(camera);
  return { x: ((p.x + 1) / 2) * window.innerWidth, y: ((1 - p.y) / 2) * window.innerHeight };
});
results.dragStart = dragStart;
await page.mouse.move(dragStart.x, dragStart.y);
await page.mouse.down();
await page.mouse.move(dragStart.x + 40, dragStart.y, { steps: 8 });
await page.mouse.up();
await drain();
results.solvedAfterDrag = await page.evaluate(() => window.__rubik.cube.isSolved());
results.dragChangedState = !results.solvedAfterDrag;

await page.screenshot({ path: '/tmp/rubik-test/shot.png' });
await page.evaluate(() => window.__rubik.reset());
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/rubik-test/shot-solved.png' });

console.log(JSON.stringify(results, null, 2));
console.log('ERRORS:', errors.length ? errors : 'none');

await browser.close();
server.close();

