import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { extname, join, normalize } from 'node:path';
import { chromium } from 'playwright-core';

const ROOT = '/tmp/rubik-test/app';
const PORT = 8233;
const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css' };
const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://localhost');
    let p = decodeURIComponent(url.pathname);
    if (p === '/') p = '/index.html';
    const file = normalize(join(ROOT, p));
    const body = await readFile(file);
    res.writeHead(200, { 'Content-Type': MIME[extname(file)] || 'application/octet-stream' });
    res.end(body);
  } catch {
    res.writeHead(404);
    res.end('not found');
  }
});
await new Promise((r) => server.listen(PORT, r));

const exe = '~/Library/Caches/ms-playwright/chromium-1234/chrome-mac-arm64/Google Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing';
const browser = await chromium.launch({
  executablePath: exe,
  headless: true,
  args: ['--enable-unsafe-swiftshader', '--use-angle=swiftshader'],
});
const page = await browser.newPage({ viewport: { width: 1100, height: 800 } });
const errors = [];
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => m.type() === 'error' && errors.push('console: ' + m.text()));

await page.goto(`http://localhost:${PORT}/index.html`, { waitUntil: 'load' });
await page.waitForFunction(() => !!window.__rubik, null, { timeout: 15000 });
await page.waitForTimeout(500);

const drain = () =>
  page.waitForFunction(() => !window.__rubik.cube.busy && window.__rubik.cube.queue.length === 0, null, { timeout: 30000 });

const results = {};

// --- Drag direction: camera straight on the front face; drag the middle
// front cubie to the right => that cubie must go from (0,0,1) to (1,0,0).
await page.evaluate(() => {
  const { camera, controls } = window.__rubik;
  camera.position.set(0, 0, 7);
  camera.up.set(0, 1, 0);
  camera.lookAt(0, 0, 0);
  camera.updateMatrixWorld(true);
  controls.target.set(0, 0, 0);
  controls.update();
});
await page.waitForTimeout(250);
const dragPoint = await page.evaluate(() => {
  const { camera } = window.__rubik;
  const cubie = window.__rubik.cube.cubies.find((c) => c.userData.home.x === 0 && c.userData.home.y === 0 && c.userData.home.z === 1);
  const p = cubie.position.clone().project(camera);
  return { x: ((p.x + 1) / 2) * window.innerWidth, y: ((1 - p.y) / 2) * window.innerHeight };
});
await page.mouse.move(dragPoint.x, dragPoint.y);
await page.mouse.down();
await page.mouse.move(dragPoint.x + 70, dragPoint.y, { steps: 10 });
await page.mouse.up();
await drain();
results.dragMovedCubie = await page.evaluate(() => {
  const cubie = window.__rubik.cube.cubies.find((c) => c.userData.home.x === 0 && c.userData.home.y === 0 && c.userData.home.z === 1);
  return cubie.position.toArray();
});

// --- Full loop: scramble, then solve with the inverse sequence.
await page.evaluate(() => window.__rubik.reset());
await drain();
await page.evaluate(() => window.__rubik.scramble());
await page.waitForTimeout(200);
await drain();
results.scrambledSolved = await page.evaluate(() => window.__rubik.cube.isSolved());
results.scrambleLength = await page.evaluate(() => window.__rubik.hud.lastScramble.length);

await page.evaluate(() => {
  const { hud, apply } = window.__rubik;
  const inverse = hud.lastScramble
    .slice()
    .reverse()
    .map((n) => (n.endsWith("'") ? n[0] : n + "'"));
  for (const n of inverse) apply(n);
});
await drain();
results.solvedAfterInverse = await page.evaluate(() => window.__rubik.cube.isSolved());
results.timerStopped = await page.evaluate(() => !window.__rubik.hud.timerRunning && window.__rubik.hud.timerElapsed > 0);
results.movesCounted = await page.evaluate(() => window.__rubik.hud.moves);
results.toastShown = await page.evaluate(() => document.getElementById('toast').classList.contains('show'));
results.toastText = await page.evaluate(() => document.getElementById('toast').textContent);

